SELECT book_id, book_name, book_code, book_type, currency, org_id, org_name, status, description, create_by, create_time, update_by, update_time FROM finance_book
AND book_name LIKE '%' || #{params.bookName} || '%'
AND book_code = #{params.bookCode}
AND book_type = #{params.bookType}
AND org_id = #{params.orgId}
AND status = #{params.status}
ORDER BY create_time DESC
